(function(){
  'use strict';
  const first={id:1,title:'データベースって何？',shortTitle:'データのきほん',intro:'まずは、小さなお店のデータをのぞいてみよう。',lessons:[{title:'データベース'},{title:'テーブル'},{title:'行・列・値'},{title:'SQLの役割'}],quiz:ChapterOne.quiz,recap:['データベースには、テーブルを保存できる','テーブルは行と列でできている。行は横、列は縦','SELECTで取り出しても、元の表は変わらない']};
  first.lessons[3]={title:'SQLの役割',lead:'「商品の名前と価格を見せて」。そんなお願いを、決まった書き方で伝えるのがSQLだよ。まずは、下のSQLをそのまま実行してみよう。',sql:'SELECT 商品名, 価格\nFROM 商品;',focus:['SELECT','FROM'],visual:'projection',tryThis:'「SQLを実行」を押して、商品名と価格だけの表になるか見てみよう。書き換えても、「初期値に戻す」でいつでも元のSQLに戻れるよ。',takeaway:'SELECTは、データを取り出すためのSQLです。表示する列を選んでも、元の表は変わりません。',variations:[]};
  const course=[first,...CourseChapters],storageKey='sql-kihon-course-v1',content=document.getElementById('lesson-content');
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let canSave=true,saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')||{};}catch{canSave=false;}
  const record=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
  const state={view:"home",menuPage:0,hasVisited:Array.isArray(saved.current),sidebarCollapsed:typeof saved.sidebarCollapsed==="boolean"?saved.sidebarCollapsed:matchMedia("(max-width:900px)").matches,chapter:1,step:0,done:new Set(Array.isArray(saved.done)?saved.done.filter(x=>typeof x==='string'):[]),finished:new Set(Array.isArray(saved.finished)?saved.finished.filter(x=>Number.isInteger(x)&&x>=1&&x<=15):[]),drafts:record(saved.drafts),quiz:record(saved.quiz),solved:record(saved.solved),question:0,wrong:null,joinProduct:1};
  const results=new Map(),chapter=()=>course[state.chapter-1],lesson=()=>chapter().lessons[state.step],key=()=>`${state.chapter}:${state.step}`;
  const answers=()=>new Set(Array.isArray(state.quiz[state.chapter])?state.quiz[state.chapter].filter(i=>Number.isInteger(i)&&i>=0&&i<3):[]);
  function save(){try{localStorage.setItem(storageKey,JSON.stringify({done:[...state.done],finished:[...state.finished],drafts:state.drafts,quiz:state.quiz,solved:state.solved,current:state.hasVisited?[state.chapter,state.step]:null,sidebarCollapsed:state.sidebarCollapsed}));}catch{canSave=false;}document.getElementById('save-status').textContent=canSave?'進み具合はこのブラウザーに保存':'この環境では進捗を保存できません';}
  const title=(t,l)=>`<h1 class="lesson-title">${esc(t)}</h1>`+CourseGuide.say(l);
  const takeaway=t=>CourseGuide.say(t,{speaker:"cornalina",label:"ここだけ覚えよう"});
  function valueHtml(v){return v===null?'<span class="null-value">NULL</span>':v===''?'<span class="empty-value">空文字</span>':esc(typeof v==='number'?Number.isInteger(v)?v.toLocaleString('ja-JP'):Number(v.toFixed(5)).toLocaleString('ja-JP'):v);}
  function tableHtml(columns,rows,{caption='結果の表',rowClass=()=>'',cellClass=()=>'',origins=[],rank=false}={}){
    return `<div class="table-scroll"><table class="data-table compact-table"><caption>${esc(caption)} <span class="tiny-label">· ${rows.length}行 / ${columns.length}列</span></caption><thead><tr>${rank?'<th scope="col">順番</th>':''}${columns.map((c,i)=>`<th scope="col" class="${cellClass(i)}">${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr class="${rowClass(i,origins[i])}">${rank?`<td class="rank-cell">${i+1}</td>`:''}${r.map((v,j)=>`<td class="${typeof v==='number'?'number ':''}${cellClass(j)}">${valueHtml(v)}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty-result" colspan="${columns.length+(rank?1:0)}">条件に合う行はありません（0行）。</td></tr>`}</tbody></table></div>`;
  }
  function draft(){const v=state.drafts[key()];return typeof v==='string'?v:lesson().challenge?.starter||lesson().sql;}
  function setDraft(sql){state.drafts[key()]=sql;save();}
  function outputForLesson(){let r=results.get(key());if(!r){r={sql:draft(),output:null,error:null,stage:0};results.set(key(),r);}return r;}
  function stageDiagram(r){
    const o=r.output,s=o.stages[r.stage];
    return `<div class="pipeline" aria-label="結果を組み立てる論理的な順序">${o.stages.map((s,i)=>`<button type="button" class="pipeline-step ${i===r.stage?'active':''}" data-stage="${i}" aria-pressed="${i===r.stage}"><span class="pipeline-number">${i+1}</span><span>${esc(s.key)}</span><small>${s.rows.length}${s.key==='GROUP BY'||s.key==='HAVING'?'組':'行'}</small></button>${i<o.stages.length-1?'<span class="pipeline-arrow" aria-hidden="true">→</span>':''}`).join('')}</div><div class="stage-caption"><div><span class="tiny-label">STEP ${r.stage+1} / ${o.stages.length}</span><h3>${esc(s.label)}</h3></div><div class="stage-arrows"><button type="button" class="icon-button" data-stage="${r.stage-1}" ${r.stage===0?'disabled':''} aria-label="前の処理へ">←</button><button type="button" class="icon-button" data-stage="${r.stage+1}" ${r.stage===o.stages.length-1?'disabled':''} aria-label="次の処理へ">→</button></div></div><p class="stage-detail">${esc(s.detail)}</p>${tableHtml(s.columns,s.rows,{caption:s.key==='GROUP BY'?'集計前のグループ（説明用）':s.key==='HAVING'?'残ったグループ（説明用）':'この段階の表',rank:s.key==='ORDER BY'||s.key==='TOP'})}`;
  }
  function groupingDiagram(o){
    const grouping=o.stages.find(s=>s.groups);if(!grouping)return'';
    const having=o.stages.find(s=>s.key==='HAVING'),kept=new Set(having?.origins.flat().map(o=>`${o.table}:${o.index}`)),db=SQLTrainer.database(state.chapter);
    return `<div class="visual-callout"><span class="visual-kicker">行を、グループの箱へ</span><div class="group-buckets">${grouping.groups.map(g=>{const retained=!having||g.origins.some(o=>kept.has(`${o.table}:${o.index}`));return `<div class="group-bucket ${retained?'':'group-excluded'}"><div class="bucket-title"><strong>${esc(g.label)}</strong><span>${g.count}行</span></div><div class="bucket-members">${g.members.map(m=>{const origin=m.origins.find(o=>o.table==='商品')||m.origins[0],data=origin&&db[origin.table];return `<span>${esc(data?origin.table==='商品'?data.rows[origin.index][1]:`${origin.table} ${origin.id}`:'行')}</span>`;}).join('')||'<span>対象の行なし</span>'}</div><p>${retained?'このまとまりごとに集計します':'HAVINGの条件に合わないグループ'}</p></div>`;}).join('')}</div></div>`;
  }
  function joinDiagram(){
    const db=SQLTrainer.database(),p=db['商品'].rows.find(r=>r[0]===state.joinProduct),orders=db['注文'].rows.filter(r=>r[1]===state.joinProduct);
    return `<div class="visual-callout"><span class="visual-kicker">同じ商品IDで、行をつなぐ</span><div class="join-product-choices" role="group" aria-label="対応を見る商品">${db['商品'].rows.map(r=>`<button type="button" data-join-product="${r[0]}" aria-pressed="${r[0]===state.joinProduct}">${esc(r[1])}</button>`).join('')}</div><div class="join-map"><div class="join-source"><small>商品テーブル</small><strong>${esc(p[1])}</strong><span>商品ID <b>${p[0]}</b></span></div><div class="join-connector" aria-hidden="true">${orders.length?'→':'⋯'}</div><div class="join-matches">${orders.length?orders.map(o=>`<div><span>注文 ${o[0]}</span><strong>商品ID ${o[1]}</strong><span>${o[2]}個</span></div>`).join(''):'<div class="unmatched"><span>一致する注文がありません</span><strong>INNER JOIN：結果に含めない<br>LEFT JOIN：右の列をNULLで補う</strong></div>'}</div></div><p class="visual-note">${orders.length>1?`「${esc(p[1])}」に対応する注文は${orders.length}行。結合結果にも${orders.length}行できます。`:orders.length?'一致する行の組み合わせが、結果の1行になります。':'LEFT JOINは、対応する注文がない商品も残せます。'} この図は商品IDだけで対応を確認するものです。</p></div>`;
  }
  function rowDiagram(o){
    const source=o.stages[0],where=o.stages.find(s=>s.key==='WHERE'),projection=o.stages.find(s=>s.key==='SELECT');
    if(['projection','calculate'].includes(lesson().visual)){const selected=new Set(projection?.columns);return `<div class="visual-callout"><span class="visual-kicker">元の表から、表示する情報を選ぶ</span>${tableHtml(source.columns,source.rows,{caption:'元の表',cellClass:i=>selected.has(source.columns[i])?'column-picked':''})}<p class="visual-note">列名がそのまま結果に現れる列を色で示しています。別名や計算結果はSELECTの段階で付きます。</p></div>`;}
    if(where){const kept=new Set(where.origins.flat().map(o=>`${o.table}:${o.index}`));return `<div class="visual-callout"><span class="visual-kicker">条件に合う行だけが、結果へ</span>${tableHtml(source.columns,source.rows,{caption:'元の表（色のついた行が残る）',origins:source.origins,rowClass:(_,origins)=>origins.some(o=>kept.has(`${o.table}:${o.index}`))?'row-kept':'row-excluded'})}<p class="visual-note">薄い行も、元のテーブルには残っています。結果に含めないだけです。</p></div>`;}
    if(lesson().visual==='null')return '<div class="visual-callout null-guide"><div><span class="null-value">NULL</span><strong>値が不明・未設定</strong></div><div><span class="empty-value">空文字</span><strong>長さ0の文字列</strong></div><div><span class="zero-value">0</span><strong>数値のゼロ</strong></div></div>';return'';
  }
  function editorPane(){
    const l=lesson(),r=outputForLesson();
    return '<div class="editor-card"><div class="editor-heading"><label for="sql-editor"><span class="flow-number">1</span> SQLを書く</label><span class="tiny-label">T-SQL</span></div><textarea id="sql-editor" class="sql-editor" maxlength="12000" spellcheck="false" autocapitalize="off" autocorrect="off" aria-describedby="editor-shortcut">'+esc(draft())+'</textarea></div><div class="run-controls"><button type="button" id="execute-sql" class="button button-primary"><span aria-hidden="true">▷</span> '+(l.challenge?'実行して答え合わせ':'SQLを実行')+'</button><button type="button" id="reset-sql" class="button button-quiet">初期値に戻す</button><span id="edit-status" role="status">'+(r.sql!==draft()?'変更あり · 実行して反映':r.submitted?'実行しました':'未実行')+'</span></div>';
  }
  function extraInstructions(){const l=lesson();return CourseGuide.say(l.challenge?l.challenge.prompt:l.tryThis,{label:l.challenge?'今回の課題':'やってみよう'})+'<div class="example-options">'+(!l.challenge?l.variations.map((v,i)=>'<button type="button" class="example-button" data-example="'+i+'">'+esc(v.label)+'</button>').join(''):'<button type="button" id="challenge-hint" class="example-button">ヒントを見る</button><button type="button" id="show-solution" class="example-button">解答例を見る</button>')+'</div><div id="challenge-help" aria-live="polite"></div>';}

  function challengeFeedback(r){return!r.submitted?'':r.correct?'<div class="challenge-feedback success"><strong>✓ 欲しい結果を作れました。</strong><p>列・値・行数・指定された並び順が課題の結果と一致しています。</p></div>':'<div class="challenge-feedback"><strong>もう一歩。課題と結果を見比べよう。</strong><p>表示する列、その順番、条件、並び順を確認してみましょう。「ヒントを見る」でも確かめられます。</p></div>';}
  function renderResult(){
    const r=outputForLesson(),head='<div class="result-heading"><h2><span class="flow-number">2</span> 実行結果</h2>'+(r.output?'<span>'+r.output.rows.length+'行・'+r.output.columns.length+'列</span>':'')+'</div>';
    if(r.error)return head+CourseGuide.say('大丈夫。ここを直して、もう一度試してみよう。')+'<div class="sql-error" role="alert"><strong>SQLを確認してみよう</strong><p>'+esc(r.error)+'</p><span>元のデータは変わっていません。「初期値に戻す」からやり直すこともできます。</span></div>';
    if(!r.output)return head+'<div class="waiting-result">'+CourseGuide.say('どんな表になるかな？ 上の「SQLを実行」を押すと、ここに結果が出るよ。')+'</div>';
    return head+tableHtml(r.output.columns,r.output.rows,{caption:'SQLで取り出した結果',rank:false})+(lesson().challenge?challengeFeedback(r):'')+(r.output.warnings.length?'<div class="query-notes">'+r.output.warnings.map(w=>'<p>'+esc(w)+'</p>').join('')+'</div>':'');
  }
  function renderExplanation(){
    const r=outputForLesson();if(!r.output)return '';
    const l=lesson(),o=r.output,visual=['join','leftjoin'].includes(l.visual)?joinDiagram():['aggregate','group','having'].includes(l.visual)?groupingDiagram(o):l.visual==='order'?'':rowDiagram(o);
    return '<section class="result-explanation"><h2>結果ができるまでを見てみよう</h2>'+CourseGuide.say('上の表が実行結果だよ。ここからは、どうやってその結果になったのかを順番に見てみよう。',{label:'もう少しくわしく'})+visual+'<div class="process-board"><div class="process-heading"><h3>途中の表をたどる</h3></div><p class="stage-detail">SQLの意味をたどる順番です。実際の内部処理の実行順序とは異なる場合があります。</p>'+stageDiagram(r)+'</div></section>';
  }

  function sources(){const db=SQLTrainer.database(state.chapter),names=[...new Set(results.get(key())?.output?.sourceTables||['商品'])];return `<details class="source-details"><summary>使っている元のテーブルを見る <span>${names.map(esc).join(' / ')}</span></summary><div>${names.filter(n=>db[n]).map(n=>tableHtml(db[n].columns,db[n].rows,{caption:`${n}テーブル`})).join('')}</div></details>`;}
  function renderSqlLesson(){const l=lesson();outputForLesson();return title(l.title,l.lead)+(l.challenge?'<div class="challenge-brief"><strong>今回の課題</strong><p>'+esc(l.challenge.prompt)+'</p></div>':'')+'<section class="paper-board sql-lab" aria-label="'+esc(l.title)+'の練習"><div class="work-area"><div class="lab-editor">'+editorPane()+'</div><div id="lab-output" aria-live="polite">'+renderResult()+'</div><div class="lesson-notes">'+extraInstructions()+takeaway(l.takeaway)+'<div id="explanation-output">'+renderExplanation()+'</div>'+sources()+'<p id="editor-shortcut" class="editor-shortcut">Ctrl / ⌘ + Enter でも実行できます</p><p class="lab-scope">SQL Serverの基本構文を使う練習用シミュレーターです。<button type="button" id="scope-details" class="text-button">対応している書き方</button></p></div></div></section>';}

  function equivalent(a,b){if(a.columns.length!==b.columns.length||a.rows.length!==b.rows.length||a.columns.some((c,i)=>c!==b.columns[i])||(b.query.order&&!a.query.order))return false;let aa=a.rows.map(r=>JSON.stringify(r)),bb=b.rows.map(r=>JSON.stringify(r));if(!b.query.order){aa.sort();bb.sort();}return aa.every((r,i)=>r===bb[i]);}
  function run(sql=draft()){setDraft(sql);const r={sql,output:null,error:null,stage:0,submitted:true};try{r.output=SQLTrainer.execute(sql,SQLTrainer.database(state.chapter));r.stage=r.output.stages.length-1;if(lesson().challenge){r.correct=equivalent(r.output,SQLTrainer.execute(lesson().challenge.solution,SQLTrainer.database(state.chapter)));if(r.correct){state.solved[key()]=true;state.done.add(key());}}}catch(e){r.error=e.message;}results.set(key(),r);save();render();document.getElementById('execute-sql')?.focus({preventScroll:true});return r;}
  function quizView(){
    if(state.finished.has(state.chapter))return completionView();const c=chapter(),q=c.quiz[state.question],answered=answers().has(state.question);
    return title('ここまでのこと、たしかめよう。','3つの問題でおさらいしましょう。間違えても、解説を見て何度でも選び直せます。')+`<section class="paper-board"><div class="board-header"><span class="board-label">QUESTION ${String(state.question+1).padStart(2,'0')}</span><div class="quiz-progress">${c.quiz.map((_,i)=>`<span class="quiz-dot ${answers().has(i)?'done':''}"></span>`).join('')} ${state.question+1} / 3</div></div><div class="work-area"><h3 class="quiz-question" id="quiz-question">${esc(q.question)}</h3>${state.chapter===1?ChapterOne.quizTable(state.question):''}<div class="quiz-options" role="group" aria-labelledby="quiz-question">${q.choices.map((choice,i)=>`<button type="button" class="quiz-option ${answered&&i===q.answer?'correct':''} ${state.wrong===i?'wrong':''}" data-answer="${i}" ${answered?'disabled':''}><span class="option-letter">${answered&&i===q.answer?'✓':['A','B','C'][i]}</span>${esc(choice)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite">${answered?`<div class="quiz-feedback">${CourseGuide.say('正解だよ。'+q.explanation)}<button type="button" id="quiz-next" class="button button-primary">${state.question===2?'この章をふりかえる':'次の問題へ'} →</button></div>`:state.wrong!==null?`<div class="quiz-feedback retry">${CourseGuide.say('もう一度、一緒に考えてみよう。'+q.hint)}</div>`:''}</div></div></section>`;
  }
  function completionView(){const c=chapter(),all=state.finished.size===15;return title(all?'SQLのきほんを、ひととおり。':`第${c.id}章、クリアです。`,all?'見る・絞る・まとめる・つなぐ。ここまで学んだことを、これからも試してみましょう。':'この章でできるようになったことを、もう一度並べてみましょう。')+`<section class="paper-board"><div class="board-header"><span class="board-label">${all?'全15章 完了':`第${c.id}章 完了`}</span><span class="tiny-label">WELL DONE</span></div><div class="work-area completion"><img class="completion-character" src="assets/carmelo.png" width="150" height="150" alt="カルメロ"><h3>${all?'自分のSQLで、欲しい結果へ。':esc(c.shortTitle)+'を学びました。'}</h3><ul class="recap-list">${c.recap.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><div class="completion-actions">${c.id<15?`<button type="button" data-chapter="${c.id+1}" class="button button-primary">第${c.id+1}章へ進む →</button>`:`<button type="button" data-open-course class="button button-primary">${all?'全15章をふりかえる':'ほかの章も学んでみる'} →</button>`}<button type="button" id="retry-quiz" class="button button-quiet">クイズをもう一度</button></div><div class="next-chapter">${c.id<15?`次の章<strong>${esc(course[c.id].title)}</strong>`:`${state.finished.size} / 15 章クリア。<strong>${all?'いつでも、この教材に戻れます。':'目次から、残りの章にも進めます。'}</strong>`}</div>${all?'<p>実際のSQL Serverでも、同じ基本構文を使います。<br>この教材は検索の入門編です。次の学習では、データの追加・更新・削除へ進めます。</p>':''}</div></section>`;}
  function renderNav(){
    const c=chapter(),names=[...c.lessons.map(l=>l.title),'たしかめよう'];document.getElementById('chapter-title').textContent=c.title;document.getElementById('chapter-title').dataset.chapter=c.id;document.getElementById('chapter-eyebrow').textContent=`CHAPTER ${String(c.id).padStart(2,'0')} / 15`;document.getElementById('chapter-intro').textContent=c.intro;
    document.getElementById('lesson-nav').innerHTML=names.map((n,i)=>`<button type="button" class="nav-step ${state.done.has(`${c.id}:${i}`)?'is-done':''}" data-step="${i}" ${state.step===i?'aria-current="step"':''}><span class="nav-number" aria-hidden="true">${state.done.has(`${c.id}:${i}`)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(n)}</span></button>`).join('');
    document.getElementById('step-label').textContent=`LESSON ${String(state.step+1).padStart(2,'0')} / ${String(names.length).padStart(2,'0')}`;document.querySelector('.chapter-label').textContent=`第${c.id}章 · ${c.shortTitle}`;
    const count=names.filter((_,i)=>state.done.has(`${c.id}:${i}`)).length;document.getElementById('progress-text').textContent=`${count} / ${names.length} レッスン`;document.getElementById('progress-fill').style.width=`${count/names.length*100}%`;const bar=document.querySelector('[role="progressbar"]');bar.setAttribute('aria-valuenow',count);bar.setAttribute('aria-valuemax',names.length);document.getElementById('course-progress').textContent=`${state.finished.size} / 15 章クリア`;
    const previous=document.getElementById('previous');previous.disabled=state.chapter===1&&state.step===0;previous.textContent=state.step===0&&state.chapter>1?'← 前の章へ':'← 前へ';const next=document.getElementById('next');next.hidden=state.step===c.lessons.length;next.textContent=state.step===c.lessons.length-1?'たしかめよう →':'次のレッスンへ →';document.getElementById('footer-note').textContent=state.chapter===15&&lesson()?.challenge&&!state.solved[key()]?'結果を作れたら、次へ進めます':'自分のペースで進めよう';document.title=`第${c.id}章 ${c.title}｜SQLのきほん`;
  }
  function renderLayout(){document.querySelector('.site-header').hidden=state.view==='home';const home=state.view!=='lesson';document.getElementById('main-menu').dataset.screen=state.view;document.getElementById('main-menu').hidden=!home;document.getElementById('app-shell').hidden=home;document.getElementById('lesson-sidebar').hidden=state.sidebarCollapsed;document.getElementById('app-shell').classList.toggle('sidebar-collapsed',state.sidebarCollapsed);document.getElementById('toggle-sidebar').setAttribute('aria-expanded',String(!state.sidebarCollapsed));document.getElementById('toggle-sidebar').textContent=state.sidebarCollapsed?'☰ 目次を開く':'☰ 目次を閉じる';document.getElementById('skip-main').setAttribute('href',home?'#main-menu':'#lesson');}
  function render(){renderLayout();if(state.view!=='lesson'){state.view==='chapters'?renderChapters():renderHome();return;}renderNav();content.innerHTML=state.step===chapter().lessons.length?quizView():state.chapter===1&&state.step<3?ChapterOne.render(state.step):renderSqlLesson();save();}
  function go(ch,step=0,{hash=true,focus=true}={}){if(!Number.isInteger(ch)||ch<1||ch>15||!Number.isInteger(step)||step<0||step>course[ch-1].lessons.length)throw new Error('章またはレッスンの番号が範囲外です。');state.view='lesson';state.hasVisited=true;state.chapter=ch;state.step=step;state.menuPage=Math.floor((ch-1)/chapterPageSize());state.wrong=null;state.question=[0,1,2].find(i=>!answers().has(i))??2;state.joinProduct=1;const route='#chapter-'+ch+'/lesson-'+(step+1);if(hash&&location.hash!==route)history.pushState(null,'',route);render();if(focus){document.getElementById('lesson').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
  function home({hash=true,focus=true}={}){state.view='home';document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(hash&&location.hash!=='#home')history.pushState(null,'','#home');render();if(focus){document.getElementById('main-menu').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
  function chapterPageSize(){return matchMedia('(min-width:1100px) and (min-height:720px)').matches?15:matchMedia('(min-width:760px) and (min-height:580px)').matches?6:matchMedia('(min-width:760px)').matches?3:matchMedia('(min-height:760px)').matches?5:3;}
  function openCourse({page=state.menuPage,hash=true,focus=true}={}){state.view='chapters';state.menuPage=Math.max(0,Math.min(Math.ceil(course.length/chapterPageSize())-1,Number.isInteger(page)?page:0));document.querySelectorAll('dialog[open]').forEach(d=>d.close());const route=state.menuPage?'#chapters/page-'+(state.menuPage+1):'#chapters';if(hash&&location.hash!==route)history.pushState(null,'',route);render();if(focus){document.getElementById('main-menu').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
  function characterIntroductions(){return '<details class="menu-character-details"><summary>キャラクター紹介</summary><div class="character-profiles"><article class="character-profile"><div class="profile-art"><img src="assets/carmelo.png" width="240" height="240" alt="白いはちまきのひよこ、カルメロ" loading="lazy"></div><div><span class="character-role">いつもの案内役</span><h3>カルメロ</h3><p>白いはちまきが目印のひよこ。やさしくて、おとなしい性格。君のペースに合わせて、ひとつずつ説明してくれます。</p><blockquote>「あわてなくて大丈夫。<br>一緒に、表を見てみよう。」</blockquote></div></article><article class="character-profile cornalina"><div class="profile-art"><img src="assets/cornalina.png" width="240" height="240" alt="穏やかに説明するコルナリーナ" loading="lazy"></div><div><span class="character-role">大切なポイントをおさらい</span><h3>コルナリーナ</h3><p>おっとりした、お姉さんのような先生。覚えておきたいことを、やさしくまとめてくれます。</p><blockquote>「ここだけ覚えておけば大丈夫。<br>少しずつ、慣れていきましょうね。」</blockquote></div></article></div></details>';}
  function renderHome(){
    document.title='SQLのきほん｜スタートメニュー';
    document.getElementById('main-menu').innerHTML='<section class="game-start" aria-labelledby="title-heading"><div class="game-scene"><img src="assets/start-scene.png" alt="白いはちまきのひよこを両腕で抱っこして、庭でほほえむ先生の全身イラスト" width="1672" height="941" fetchpriority="high"></div><div class="game-shade" aria-hidden="true"></div><div class="game-frame" aria-hidden="true"></div><div class="game-menu"><div class="game-copy"><p class="game-edition">図で学ぶ SQL Server 入門</p><h1 id="title-heading"><span class="game-logo-sql">SQL</span><span class="game-logo-jp">のきほん</span></h1><p class="game-tagline">見て、さわって、一歩ずつ。</p></div><nav class="game-actions" aria-label="スタートメニュー"><a class="game-action is-primary" href="#chapters" data-open-course><span class="game-cursor" aria-hidden="true">▷</span>はじめる</a>'+(state.hasVisited?'<button type="button" class="game-action" data-resume>つづきから <small>第'+state.chapter+'章</small></button>':'')+'</nav><p class="game-progress">'+state.finished.size+' / 15 章クリア</p></div></section>'+characterIntroductions();
  }
  function renderChapters(){
    document.title='章を選ぶ｜SQLのきほん';
    const size=chapterPageSize(),pages=Math.ceil(course.length/size);state.menuPage=Math.max(0,Math.min(pages-1,state.menuPage));
    const labels=['データベースって何？','はじめてのSQL','条件に合う行を探す','条件を組み合わせる','いろいろな探し方','並べ替えと上位表示','結果の表示を整える','値が入っていないとき','件数や合計を求める','種類ごとに集計する','集計した結果を絞る','2つの表をつなぐ','相手がいない行も残す','書く順番と処理の順番','自分でSQLを書いてみる'];
    const topics=['表・行・列・SQLの役割','SELECT / FROM','WHERE / 比較記号','AND / OR / 括弧','IN / BETWEEN / LIKE','ORDER BY / TOP','AS / 計算 / DISTINCT','NULL / IS NULL','COUNT / SUM / AVG','GROUP BY','HAVING / WHEREとの違い','INNER JOIN','LEFT JOIN','論理的な処理の順序','3つの総合演習'];
    const start=state.menuPage*size,visible=course.slice(start,start+size);
    document.getElementById('main-menu').innerHTML='<section class="chapter-picker" aria-labelledby="picker-title"><div class="picker-heading"><div><a href="#home" data-home class="back-to-title">← タイトルへ</a><h1 id="picker-title">学ぶ章を選ぼう</h1></div><div class="picker-progress"><strong>'+state.finished.size+'</strong><span> / 15 章クリア</span></div></div><p class="picker-instruction">はじめてなら第1章から。気になる章からでも学べます。</p><div class="chapter-tile-grid">'+visible.map(c=>'<a class="chapter-tile '+(state.finished.has(c.id)?'is-complete':'')+'" href="#chapter-'+c.id+'/lesson-1" data-chapter="'+c.id+'" aria-label="第'+c.id+'章 '+esc(c.title)+'。'+esc(topics[c.id-1])+(state.finished.has(c.id)?'。クリア済み':'')+'"><span class="tile-index"><small>第</small>'+String(c.id).padStart(2,'0')+'<small>章</small></span><div class="tile-body"><h2>'+labels[c.id-1]+'</h2><p>'+topics[c.id-1]+'</p></div>'+(state.finished.has(c.id)?'<span class="tile-done" aria-hidden="true">✓</span>':'')+'</a>').join('')+'</div><div class="picker-footer">'+(pages>1?'<nav class="chapter-pagination" aria-label="章一覧のページ"><button type="button" class="button button-quiet" data-menu-page="'+(state.menuPage-1)+'" '+(state.menuPage===0?'disabled':'')+'>← 前へ</button><span aria-live="polite">第'+(start+1)+'〜'+Math.min(start+size,15)+'章 <small>'+ (state.menuPage+1)+' / '+pages+'</small></span><button type="button" class="button button-primary" data-menu-page="'+(state.menuPage+1)+'" '+(state.menuPage===pages-1?'disabled':'')+'>次へ →</button></nav>':'<p>全15章 · 各章の最後に、おさらいクイズ</p>')+'</div></section>'+characterIntroductions();
  }
  let menuResize;
  window.addEventListener('resize',()=>{clearTimeout(menuResize);menuResize=setTimeout(()=>{if(state.view==='chapters'){renderChapters();const route=state.menuPage?'#chapters/page-'+(state.menuPage+1):'#chapters';history.replaceState(null,'',route);}},100);});
  function openReference(){
    const rows=[['列を取り出す','SELECT 商品名, 価格 FROM 商品;',2],['行を絞る','WHERE 価格 >= 500',3],['条件を組み合わせる',"WHERE カテゴリ = N'文房具' AND 価格 < 300",4],['範囲・候補・部分一致',"WHERE 価格 BETWEEN 100 AND 500\nWHERE 商品ID IN (1, 3)\nWHERE 商品名 LIKE N'%ノート%'",5],['並べ替え・上位件数','SELECT TOP (3) 商品名, 価格 FROM 商品\nORDER BY 価格 DESC, 商品ID;',6],['名前・計算・重複除去','SELECT 価格 * 在庫 AS 在庫金額 FROM 商品;\nSELECT DISTINCT カテゴリ FROM 商品;',7],['NULLを調べる','WHERE メモ IS NULL\nWHERE メモ IS NOT NULL',8],['集計する','COUNT(*) / SUM(価格) / AVG(価格)\nMIN(価格) / MAX(価格)',9],['グループ別に集計','SELECT カテゴリ, SUM(価格) AS 合計\nFROM 商品 GROUP BY カテゴリ;',10],['集計した後の条件','GROUP BY カテゴリ\nHAVING SUM(価格) >= 1000',11],['2つの表をつなぐ','FROM 商品 AS p\nINNER JOIN 注文 AS o ON p.商品ID = o.商品ID',12],['左の行を残してつなぐ','FROM 商品 AS p\nLEFT JOIN 注文 AS o ON p.商品ID = o.商品ID',13]];
    document.getElementById('reference-content').innerHTML=`<p class="dialog-intro">一部はSQLの部品です。章に戻ると、文全体の例と説明を見られます。</p><div class="reference-list">${rows.map(([label,sql,ch])=>`<section><div><strong>${esc(label)}</strong><button type="button" data-chapter="${ch}" class="text-button">第${ch}章へ →</button></div><pre>${esc(sql)}</pre></section>`).join('')}</div><div class="scope-note"><h3>この練習画面の範囲</h3><p>教材で紹介するSELECT文を、ブラウザー内のサンプルデータで再現します。SQL Server本体への接続は行いません。複数文、サブクエリ、WITH、CASE、ウィンドウ関数、追加・更新・削除などは対象外です。</p><p>照合順序や暗黙の型変換、桁数・オーバーフローなど、SQL Serverのすべての動作を再現するものではありません。文字の比較・並び順はこの教材独自の規則で、大文字と小文字を区別します。</p><p>第8章から商品テーブルに「メモ」列が加わります。進捗と入力したSQLは、このブラウザー内に保存されます。</p><a href="https://learn.microsoft.com/ja-jp/sql/t-sql/queries/select-transact-sql" target="_blank" rel="noreferrer">Microsoft公式：SELECTの書き方 ↗</a></div>`;document.getElementById('reference-dialog').showModal();
  }
  document.addEventListener('input',e=>{if(e.target.id==='sql-editor'){setDraft(e.target.value);document.getElementById('edit-status').textContent='変更あり · 実行して反映';}});
  document.addEventListener('keydown',e=>{if(e.target.id==='sql-editor'&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run(e.target.value);}});
  document.addEventListener('click',e=>{
    if(!(e.target instanceof Element))return;const t=e.target,close=t.closest('[data-close-dialog]');if(close){document.getElementById(close.dataset.closeDialog).close();return;}
    if(t.closest('[data-home]')){e.preventDefault();home();return;}if(t.closest('[data-open-course]')){e.preventDefault();openCourse();return;}const menuPage=t.closest('[data-menu-page]');if(menuPage&&!menuPage.disabled){openCourse({page:Number(menuPage.dataset.menuPage)});return;}if(t.closest('[data-resume]')){go(state.chapter,state.step);return;}if(t.closest('[data-toggle-sidebar]')){state.sidebarCollapsed=!state.sidebarCollapsed;renderLayout();save();document.getElementById('toggle-sidebar').focus({preventScroll:true});return;}if(t.closest('#open-reference,#scope-details')){openReference();return;}
    const ch=t.closest('a[data-chapter],button[data-chapter]');if(ch){e.preventDefault();document.querySelectorAll('dialog[open]').forEach(d=>d.close());go(Number(ch.dataset.chapter));return;}
    const nav=t.closest('[data-step]');if(nav){go(state.chapter,Number(nav.dataset.step));return;}
    if(state.chapter===1&&state.step<3){const focus=ChapterOne.handle(e);if(focus){render();document.querySelector(focus)?.focus({preventScroll:true});return;}}
    if(t.closest('#reset-sql')){setDraft(lesson().challenge?.starter||lesson().sql);results.delete(key());state.joinProduct=1;render();document.getElementById('edit-status').textContent='初期値に戻しました';document.getElementById('sql-editor').focus({preventScroll:true});return;}
    if(t.closest('#execute-sql')){run(document.getElementById('sql-editor').value);return;}
    const example=t.closest('[data-example]');if(example){const v=example.dataset.example;setDraft(v==='original'?lesson().challenge?.starter||lesson().sql:lesson().variations[Number(v)].sql);results.delete(key());render();document.getElementById('sql-editor').focus({preventScroll:true});return;}
    const stage=t.closest('[data-stage]');if(stage&&!stage.disabled){const r=results.get(key()),i=Number(stage.dataset.stage);if(!r?.output||i<0||i>=r.output.stages.length)return;r.stage=i;document.getElementById('explanation-output').innerHTML=renderExplanation();document.querySelector(`.pipeline [data-stage="${i}"]`)?.focus({preventScroll:true});return;}
    const join=t.closest('[data-join-product]');if(join){state.joinProduct=Number(join.dataset.joinProduct);document.getElementById('explanation-output').innerHTML=renderExplanation();document.querySelector(`[data-join-product="${state.joinProduct}"]`).focus({preventScroll:true});return;}
    if(t.closest('#challenge-hint')){document.getElementById('challenge-help').innerHTML=`<div class="quiz-feedback"><strong>使う部品</strong><p>${esc(lesson().focus.join(' → '))}</p><p>${esc(lesson().takeaway)}</p></div>`;return;}
    if(t.closest('#show-solution')){document.getElementById('challenge-help').innerHTML=`<div class="quiz-feedback"><strong>解答例</strong><pre class="solution-code">${esc(lesson().challenge.solution)}</pre><p>書き方を見比べて、自分の入力欄で動かしてみましょう。</p></div>`;return;}
    const answer=t.closest('[data-answer]');if(answer){if(answers().has(state.question))return;const n=Number(answer.dataset.answer);if(n===chapter().quiz[state.question].answer){const a=answers();a.add(state.question);state.quiz[state.chapter]=[...a];state.wrong=null;render();document.getElementById('quiz-next').focus({preventScroll:true});}else{state.wrong=n;render();document.querySelector(`[data-answer="${n}"]`).focus({preventScroll:true});}return;}
    if(t.closest('#quiz-next')){if(!answers().has(state.question))return;if(state.question<2){state.question++;state.wrong=null;render();}else{const missing=state.chapter===15?chapter().lessons.findIndex((_,i)=>!state.solved[`15:${i}`]):-1;if(missing>=0){go(15,missing);document.getElementById('challenge-help').innerHTML='<div class="quiz-feedback">あとはこちらの演習です。SQLを書いて欲しい結果を作ったら、全体をふりかえりましょう。</div>';return;}state.finished.add(state.chapter);for(let i=0;i<=chapter().lessons.length;i++)state.done.add(`${state.chapter}:${i}`);render();}document.getElementById('lesson').focus({preventScroll:true});document.getElementById('lesson').scrollIntoView({block:'start',behavior:'instant'});return;}
    if(t.closest('#retry-quiz')){state.quiz[state.chapter]=[];state.finished.delete(state.chapter);state.done.delete(key());state.question=0;state.wrong=null;render();return;}
    if(t.closest('#next')){if(lesson()?.challenge&&!state.solved[key()]){document.getElementById('challenge-help').innerHTML='<div class="quiz-feedback">SQLを実行して、課題の結果を作ってみましょう。解答例を見ながらでも大丈夫です。</div>';return;}state.done.add(key());go(state.chapter,state.step+1);return;}
    if(t.closest('#previous')){if(state.step>0)go(state.chapter,state.step-1);else if(state.chapter>1)go(state.chapter-1,course[state.chapter-2].lessons.length);}
  });
  for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  function fromHash(){if(location.hash==='#home'||!location.hash){home({hash:false,focus:false});return true;}const menu=location.hash.match(/^#chapters(?:\/page-(\d+))?$/);if(menu){openCourse({page:menu[1]?Number(menu[1])-1:0,hash:false,focus:false});return true;}const m=location.hash.match(/^#chapter-(\d+)\/lesson-(\d+)$/);if(!m)return false;const ch=Number(m[1]),st=Number(m[2])-1;if(ch<1||ch>15||st<0||st>course[ch-1].lessons.length)return false;go(ch,st,{hash:false,focus:false});return true;}
  window.addEventListener('hashchange',()=>fromHash());
  const p=Array.isArray(saved.current)?saved.current:[1,0];if(Number.isInteger(p[0])&&p[0]>=1&&p[0]<=15&&Number.isInteger(p[1])&&p[1]>=0&&p[1]<=course[p[0]-1].lessons.length){state.chapter=p[0];state.step=p[1];}else state.hasVisited=false;
  if(!fromHash())home({hash:false,focus:false});
  const context=document.modelContext;
  if(context?.registerTool){const lifecycle=new AbortController(),tools=[
    {name:'read_sql_course',title:'SQL教材の状態を読む',description:'全15章の現在位置と学習進捗を読みます。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{view:state.view,chapter:state.chapter,lesson:state.step+1,chapterTitle:chapter().title,completedChapters:[...state.finished],sidebarCollapsed:state.sidebarCollapsed};}},
    {name:'navigate_sql_course',title:'章・レッスンを開く',description:'指定した章とレッスンへ移動します。移動だけでは完了にしません。',inputSchema:{type:'object',properties:{chapter:{type:'integer',minimum:1,maximum:15},lesson:{type:'integer',minimum:1,maximum:5}},required:['chapter','lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){go(input?.chapter,Number.isInteger(input?.lesson)?input.lesson-1:NaN);return{chapter:state.chapter,lesson:state.step+1};}},
    {name:'run_training_select',title:'教材でSELECTを試す',description:'現在のSQLレッスンで教材データに対するSELECTを実行。結果、入力内容、演習進捗を画面に反映します。実際のSQL Serverには接続しません。',inputSchema:{type:'object',properties:{sql:{type:'string',maxLength:12000}},required:['sql'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(state.view!=='lesson'||!lesson()?.sql||typeof input?.sql!=='string')throw new Error('SQL入力欄のあるレッスンを開き、sql文字列を指定します。');const r=run(input.sql);return r.error?{error:r.error}:{columns:r.output.columns,rows:r.output.rows,exerciseCorrect:r.correct??null};}}
  ];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
})();
